import{_ as s,H as e,f as n,i as t}from"./chunks/framework.DIv0Dgmf.js";const u=JSON.parse('{"title":"第十二章：日常工作流实战","description":"整合前面所学，体验完整的 AI 辅助开发流程","frontmatter":{"title":"第十二章：日常工作流实战","description":"整合前面所学，体验完整的 AI 辅助开发流程"},"headers":[],"relativePath":"guide/3-practical-workflows/12-realistic-workflow.md","filePath":"guide/3-practical-workflows/12-realistic-workflow.md"}'),p={name:"guide/3-practical-workflows/12-realistic-workflow.md"};function l(i,a,o,d,c,r){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="第十二章-日常工作流实战" tabindex="-1">第十二章：日常工作流实战 <a class="header-anchor" href="#第十二章-日常工作流实战" aria-label="Permalink to &quot;第十二章：日常工作流实战&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>整合前十一章所学，体验一个完整的 AI 辅助开发工作流。</p></div><h2 id="本章内容" tabindex="-1">本章内容 <a class="header-anchor" href="#本章内容" aria-label="Permalink to &quot;本章内容&quot;">​</a></h2><p>这一章不教新功能，而是把前面学到的技能串联起来，通过三个真实场景体验完整的工作流。</p><p>每个场景都是独立的小练习，你可以选择一个或多个来完成。</p><hr><h2 id="场景一-接需求-→-写代码-→-自测-→-提交" tabindex="-1">场景一：接需求 → 写代码 → 自测 → 提交 <a class="header-anchor" href="#场景一-接需求-→-写代码-→-自测-→-提交" aria-label="Permalink to &quot;场景一：接需求 → 写代码 → 自测 → 提交&quot;">​</a></h2><p>这是最常见的日常场景。</p><h3 id="需求描述" tabindex="-1">需求描述 <a class="header-anchor" href="#需求描述" aria-label="Permalink to &quot;需求描述&quot;">​</a></h3><blockquote><p>&quot;帮我在博客系统里加一个功能：显示每篇文章的阅读量。&quot;</p></blockquote><h3 id="完整流程" tabindex="-1">完整流程 <a class="header-anchor" href="#完整流程" aria-label="Permalink to &quot;完整流程&quot;">​</a></h3><p><strong>第一步：理解需求</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：帮我看看现有的博客系统结构，了解一下文章相关的代码是怎么组织的。</span></span>
<span class="line"><span>Claude：（分析项目结构，给出代码概览）</span></span></code></pre></div><p><strong>第二步：设计实现方案</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：这个功能应该怎么实现比较合理？</span></span>
<span class="line"><span>Claude：（给出方案建议，包括数据库改动、代码逻辑、模板更新）</span></span>
<span class="line"><span>你：好，就按你说的方案来</span></span></code></pre></div><p><strong>第三步：让 Claude 写代码</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：帮我实现这个功能，需要修改哪些文件？</span></span>
<span class="line"><span>Claude：（逐个修改文件，每次修改前会询问你确认）</span></span></code></pre></div><p><strong>第四步：自测</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：功能写完了，帮我测试一下</span></span>
<span class="line"><span>Claude：（指导你如何测试，可能需要手动访问页面验证）</span></span></code></pre></div><p><strong>第五步：提交代码</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：帮我写 commit message 并提交</span></span>
<span class="line"><span>Claude：（生成规范的 commit message）</span></span></code></pre></div><hr><h2 id="场景二-接手旧项目-→-理解代码-→-修-bug" tabindex="-1">场景二：接手旧项目 → 理解代码 → 修 bug <a class="header-anchor" href="#场景二-接手旧项目-→-理解代码-→-修-bug" aria-label="Permalink to &quot;场景二：接手旧项目 → 理解代码 → 修 bug&quot;">​</a></h2><p>接手的项目不熟悉？Claude 帮你快速理解。</p><h3 id="需求描述-1" tabindex="-1">需求描述 <a class="header-anchor" href="#需求描述-1" aria-label="Permalink to &quot;需求描述&quot;">​</a></h3><blockquote><p>&quot;我接手了一个旧项目，有人在里面埋了个 bug，需要我找出来并修复。&quot;</p></blockquote><h3 id="完整流程-1" tabindex="-1">完整流程 <a class="header-anchor" href="#完整流程-1" aria-label="Permalink to &quot;完整流程&quot;">​</a></h3><p><strong>第一步：了解项目</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：这个项目是做什么的？帮我分析一下结构</span></span>
<span class="line"><span>Claude：（介绍项目类型、技术栈、目录结构）</span></span></code></pre></div><p><strong>第二步：找到问题代码</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：这个项目有个 bug，用户反映【具体问题描述】</span></span>
<span class="line"><span>Claude：（分析可能的问题位置）</span></span></code></pre></div><p><strong>第三步：定位并修复</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：帮我看看这几行代码是不是有问题</span></span>
<span class="line"><span>Claude：（分析后给出结论）</span></span>
<span class="line"><span>你：确实是这里的问题，帮我修复</span></span>
<span class="line"><span>Claude：（修改代码）</span></span></code></pre></div><p><strong>第四步：验证修复</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：帮我再检查一遍，确保没有引入新问题</span></span>
<span class="line"><span>Claude：（审查代码，确认修复正确）</span></span></code></pre></div><hr><h2 id="场景三-代码审查-→-优化-→-完成" tabindex="-1">场景三：代码审查 → 优化 → 完成 <a class="header-anchor" href="#场景三-代码审查-→-优化-→-完成" aria-label="Permalink to &quot;场景三：代码审查 → 优化 → 完成&quot;">​</a></h2><p>用 Claude 做 Code Review 是个很好的习惯。</p><h3 id="需求描述-2" tabindex="-1">需求描述 <a class="header-anchor" href="#需求描述-2" aria-label="Permalink to &quot;需求描述&quot;">​</a></h3><blockquote><p>&quot;我写了一段代码，想让 Claude 帮忙审查一下有没有问题，然后优化一下。&quot;</p></blockquote><h3 id="完整流程-2" tabindex="-1">完整流程 <a class="header-anchor" href="#完整流程-2" aria-label="Permalink to &quot;完整流程&quot;">​</a></h3><p><strong>第一步：提交代码审查</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：请审查 \`routes.py\` 中的用户认证相关代码</span></span>
<span class="line"><span>Claude：（逐个指出潜在问题、安全风险、优化建议）</span></span></code></pre></div><p><strong>第二步：逐个讨论</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：第二个问题怎么修复比较好？</span></span>
<span class="line"><span>Claude：（给出具体修复方案）</span></span>
<span class="line"><span>你：好，帮我改一下</span></span>
<span class="line"><span>Claude：（修改）</span></span></code></pre></div><p><strong>第三步：优化建议</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：除了 bug 修复，还有哪些可以优化的地方？</span></span>
<span class="line"><span>Claude：（从性能、可读性、安全性等角度给出建议）</span></span></code></pre></div><p><strong>第四步：实施优化</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：帮我把重要的优化实施了</span></span>
<span class="line"><span>Claude：（逐一修改，每次确认）</span></span></code></pre></div><hr><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>从下面三个场景中选一个，用 Claude 完整走一遍：</p><ol><li><strong>场景 A</strong>：给博客加一个&quot;评论功能&quot;（从设计到实现到测试）</li><li><strong>场景 B</strong>：找一个开源项目，用 Claude 分析它的架构和代码</li><li><strong>场景 C</strong>：把自己的某个旧项目交给 Claude 做全面代码审查</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 遇到 Claude 理解错了怎么办？</strong></p><p>A: 越具体越好。把错误信息和上下文一起给 Claude，它会更准确地定位问题。</p><p><strong>Q: 场景太复杂，跟不上怎么办？</strong></p><p>A: 把大任务拆成小任务。Claude 每次只做一件事，出错的概率就会降低。</p><p><strong>Q: 担心 Claude 写错代码？</strong></p><p>A: 这是正确的谨慎。每次修改前 Claude 都会给你确认机会，最后运行代码的也是你自己。</p><hr><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>恭喜你完成了所有实战内容。下一章是最后一章，我们会聊聊接下来可以学什么。</p><p><a href="/claude-code-guide/guide/5-next-steps/18-next-steps.html">👉 第十八章：继续学习之路</a></p>`,65)])])}const g=s(p,[["render",l]]);export{u as __pageData,g as default};
